{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Validate required fields
    if not nodes:
        raise ValueError("nodes is empty")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be a dict")
    for n in nodes:
        if n not in core_distance:
            raise ValueError(f"core_distance missing entry for {n}")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    # Compute mutual reachability for each edge and canonicalize endpoints
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize undirected endpoints: smaller string first
        if u > v:
            u, v = v, u
        mr_edges.append((mr, u, v))

    # Sort by reachability then by endpoint strings for determinism
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Kruskal's algorithm with union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; cannot form a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
